CREATE TABLE IF NOT EXISTS users(id SERIAL PRIMARY KEY,username TEXT UNIQUE NOT NULL,display_name TEXT NOT NULL,pass_hash TEXT NOT NULL,role TEXT NOT NULL DEFAULT 'user',balance BIGINT NOT NULL DEFAULT 0 CHECK(balance>=0),locked BOOLEAN NOT NULL DEFAULT false,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS categories(id SERIAL PRIMARY KEY,name TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',image TEXT NOT NULL DEFAULT '',note TEXT NOT NULL DEFAULT '',sort INT NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS products(id SERIAL PRIMARY KEY,category_id INT NOT NULL REFERENCES categories(id) ON DELETE CASCADE,name TEXT NOT NULL,price BIGINT NOT NULL CHECK(price>=0),description TEXT NOT NULL DEFAULT '',image TEXT NOT NULL DEFAULT '',download_url TEXT NOT NULL DEFAULT '',stock INT,sold INT NOT NULL DEFAULT 0,active BOOLEAN NOT NULL DEFAULT true,sort INT NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS orders(id SERIAL PRIMARY KEY,code TEXT UNIQUE NOT NULL,user_id INT NOT NULL REFERENCES users(id),product_id INT,product_name TEXT NOT NULL,download_url TEXT NOT NULL DEFAULT '',qty INT NOT NULL,unit_price BIGINT NOT NULL,total BIGINT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS transactions(id SERIAL PRIMARY KEY,code TEXT UNIQUE NOT NULL,user_id INT NOT NULL REFERENCES users(id),type TEXT NOT NULL,amount BIGINT NOT NULL,status TEXT NOT NULL,ref TEXT UNIQUE,note TEXT NOT NULL DEFAULT '',created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS bank(id INT PRIMARY KEY DEFAULT 1 CHECK(id=1),bank_name TEXT NOT NULL DEFAULT '',account_name TEXT NOT NULL DEFAULT '',account_number TEXT NOT NULL DEFAULT '',qr_image TEXT NOT NULL DEFAULT '',enabled BOOLEAN NOT NULL DEFAULT true);
INSERT INTO bank(id) VALUES(1) ON CONFLICT DO NOTHING;
CREATE TABLE IF NOT EXISTS settings(key TEXT PRIMARY KEY,value TEXT NOT NULL DEFAULT '');
INSERT INTO settings(key,value) VALUES('banner',''),('intro','Cửa hàng sản phẩm hỗ trợ gaming chuyên nghiệp.'),('notice',''),('phone','0796170459') ON CONFLICT DO NOTHING;
CREATE TABLE IF NOT EXISTS admin_logs(id SERIAL PRIMARY KEY,admin_id INT NOT NULL,action TEXT NOT NULL,detail TEXT NOT NULL DEFAULT '',created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_products_cat ON products(category_id);
CREATE INDEX IF NOT EXISTS idx_orders_user ON orders(user_id);
CREATE INDEX IF NOT EXISTS idx_tx_user ON transactions(user_id,created_at);
